const fs = require('fs');
const data = fs.readFileSync('/workspace/world.db');
// Search for the subject string in the binary
const searchStr = 'High Priority: Onboarding Equipment Setup Needed';
const idx = data.indexOf(searchStr);
if (idx >= 0) {
  // Print surrounding context
  const start = Math.max(0, idx - 500);
  const end = Math.min(data.length, idx + 2000);
  const slice = data.slice(start, end);
  // Print printable characters
  let result = '';
  for (let i = 0; i < slice.length; i++) {
    const c = slice[i];
    if (c >= 32 && c < 127) result += String.fromCharCode(c);
    else result += ' ';
  }
  console.log(result);
} else {
  console.log('Not found in binary scan');
}
"

