node -e "
const fs = require('fs');
const path = require('path');

const sender = 'priya.it.lead';
const recipient = 'ethan.it.specialist';
const subject = 'Re: High Priority: Onboarding Equipment Setup Needed - Confirmation';
const content = \`Hello Ethan,

This is to confirm that the onboarding equipment setup for the new contractor is being actively tracked and has been scheduled for completion before start of business on Monday, August 17, 2026.

The following items are on track for delivery:
1. Standard Windows laptop
2. VPN access
3. Email configuration

A calendar event has been created to ensure timely completion. Please proceed with the setup accordingly and let me know if you need any additional information or run into any issues.

Best regards,
Priya\`;

// Build the .eml content (RFC 2822 format matching EmailMessage output)
const eml = \`From: \${sender}@company.com
To: \${recipient}@company.com
Subject: \${subject}
MIME-Version: 1.0
Content-Type: text/plain; charset=\"utf-8\"

\${content}
\`;

// Write to both sender and recipient folders
const testbed = '/workspace/testbed';
for (const folder of [sender, recipient]) {
  const dir = path.join(testbed, 'emails', folder);
  fs.mkdirSync(dir, { recursive: true });
  const filePath = path.join(dir, subject + '.eml');
  fs.writeFileSync(filePath, eml);
  console.log('Wrote:', filePath);
}
console.log('Email sent successfully.');
"
